-- ============================================================
-- UPDATE RLS: 2-hour prediction lockout
-- ============================================================
DROP POLICY IF EXISTS "Users can insert own predictions" ON public.predictions;
DROP POLICY IF EXISTS "Users can update own pending predictions" ON public.predictions;

CREATE POLICY "Users can insert own predictions"
  ON public.predictions FOR INSERT
  WITH CHECK (
    auth.uid() = user_id AND
    EXISTS (
      SELECT 1 FROM public.matches m
      WHERE m.id = match_id
        AND m.status = 'scheduled'
        AND m.match_date > now() + interval '2 hours'
    )
  );

CREATE POLICY "Users can update own pending predictions"
  ON public.predictions FOR UPDATE
  USING (
    auth.uid() = user_id AND
    EXISTS (
      SELECT 1 FROM public.matches m
      WHERE m.id = match_id
        AND m.status = 'scheduled'
        AND m.match_date > now() + interval '2 hours'
    )
  );
